/**
 * list_examples tool — list or filter working GraphQL examples.
 */
import { z } from 'zod';
export const listExamplesSchema = z.object({
    topic: z.string().max(200).optional().describe('Optional topic to filter examples (e.g. "pagination", "token", "wallet")'),
});
/** Source files that contain examples */
const EXAMPLE_SOURCES = [
    'examples/basic-queries.md',
    'examples/integration-patterns.md',
    'examples/multi-step-workflows.md',
];
export function handleListExamples(input, sections) {
    // Filter to example sections only
    let examples = sections.filter(s => EXAMPLE_SOURCES.includes(s.sourceFile));
    if (examples.length === 0) {
        return 'No example content available. Data files may be missing — try reinstalling the package.';
    }
    // Filter by topic if provided
    if (input.topic) {
        const topicLower = input.topic.toLowerCase();
        examples = examples.filter(s => s.title.toLowerCase().includes(topicLower) ||
            s.body.toLowerCase().includes(topicLower));
        if (examples.length === 0) {
            return `No examples found matching "${input.topic}". Try a broader keyword like "token", "transaction", "pagination", "authentication", or "wallet".`;
        }
    }
    if (input.topic) {
        // Detailed output for filtered results
        const results = examples.map(s => `## ${s.title}\n*Source: ${s.sourceFile}*\n\n${s.body}`);
        return results.join('\n\n---\n\n');
    }
    // Summary list for unfiltered results
    const grouped = {};
    for (const s of examples) {
        if (!grouped[s.sourceFile])
            grouped[s.sourceFile] = [];
        grouped[s.sourceFile].push(s.title);
    }
    const lines = Object.entries(grouped).map(([file, titles]) => `**${file}:**\n${titles.map(t => `  - ${t}`).join('\n')}`);
    return `Available examples (${examples.length} total):\n\n${lines.join('\n\n')}\n\nUse the \`topic\` parameter to get full details for a specific topic.`;
}
